import Foundation

struct PulsePlaylist: Identifiable, Codable {
    let id: String
    let name: String
    let description: String
    var tracks: [PulseTrack]
    let createdAt: Date
    let isPublic: Bool
}

struct PulseTrack: Identifiable, Codable {
    let id: String
    let name: String
    let artist: String
    let energy: Double
    let valence: Double
    let tempo: Int
    let genre: String?
}

@Observable
class PlaylistManager {
    var playlists: [PulsePlaylist] = []
    var isLoading = false

    func createPlaylist(name: String, tracks: [PulseTrack], isPublic: Bool) {
        let playlist = PulsePlaylist(
            id: UUID().uuidString,
            name: name,
            description: "Created with PULSE",
            tracks: tracks,
            createdAt: Date(),
            isPublic: isPublic
        )
        playlists.append(playlist)
    }
}

import Foundation
import HealthKit

@Observable
class HeartRateModel {
    var currentHeartRate: Int = 0
    var isMonitoring = false
    var userAge: Int = 30
    var restingHeartRate: Int = 60

    private let healthStore = HKHealthStore()

    func startMonitoring() {
        isMonitoring = true
        requestHealthKitAuthorization()
    }

    func stopMonitoring() {
        isMonitoring = false
    }

    private func requestHealthKitAuthorization() {
        let heartRateType = HKQuantityType.quantityType(forIdentifier: .heartRate)!

        healthStore.requestAuthorization(toShare: [], read: [heartRateType]) { success, error in
            if success {
                print("HealthKit authorization granted")
                // Query recent heart rate data
                self.queryRecentHeartRate()
            } else if let error = error {
                print("HealthKit authorization error: \(error.localizedDescription)")
            }
        }
    }

    private func queryRecentHeartRate() {
        let heartRateType = HKQuantityType.quantityType(forIdentifier: .heartRate)!
        let sortDescriptors = [NSSortDescriptor(key: HKSampleAttributeKeyStartDate, ascending: false)]
        let query = HKSampleQuery(sampleType: heartRateType, predicate: nil, limit: 1, sortDescriptors: sortDescriptors) { _, samples, _ in
            if let sample = samples?.first as? HKQuantitySample {
                let heartRateUnit = HKUnit(from: "count/min")
                DispatchQueue.main.async {
                    self.currentHeartRate = Int(sample.quantity.doubleValue(for: heartRateUnit))
                }
            }
        }

        healthStore.execute(query)
    }
}

