import Foundation

@Observable
class ConfigService {
    static let shared = ConfigService()

    private let userDefaults = UserDefaults.standard
    private let configKey = "com.pulse.config"

    var includeLiked: Bool {
        get { userDefaults.bool(forKey: "includeLiked") || true }
        set { userDefaults.set(newValue, forKey: "includeLiked") }
    }

    var includeRecent: Bool {
        get { userDefaults.bool(forKey: "includeRecent") || true }
        set { userDefaults.set(newValue, forKey: "includeRecent") }
    }

    var makePublic: Bool {
        get { userDefaults.bool(forKey: "makePublic") || true }
        set { userDefaults.set(newValue, forKey: "makePublic") }
    }

    var maxTracks: Int {
        get { userDefaults.integer(forKey: "maxTracks") == 0 ? 200 : userDefaults.integer(forKey: "maxTracks") }
        set { userDefaults.set(newValue, forKey: "maxTracks") }
    }

    var selectedGenres: [String] {
        get { userDefaults.array(forKey: "selectedGenres") as? [String] ?? [] }
        set { userDefaults.set(newValue, forKey: "selectedGenres") }
    }

    var energyRange: [Double] {
        get { userDefaults.array(forKey: "energyRange") as? [Double] ?? [0.4, 0.9] }
        set { userDefaults.set(newValue, forKey: "energyRange") }
    }

    var valenceRange: [Double] {
        get { userDefaults.array(forKey: "valenceRange") as? [Double] ?? [0.3, 0.8] }
        set { userDefaults.set(newValue, forKey: "valenceRange") }
    }

    var tempoRange: [Int] {
        get { userDefaults.array(forKey: "tempoRange") as? [Int] ?? [90, 160] }
        set { userDefaults.set(newValue, forKey: "tempoRange") }
    }

    func saveConfig() {
        userDefaults.synchronize()
    }

    func loadConfig() -> [String: Any]? {
        let config: [String: Any] = [
            "includeLiked": includeLiked,
            "includeRecent": includeRecent,
            "makePublic": makePublic,
            "maxTracks": maxTracks,
            "selectedGenres": selectedGenres,
            "energyRange": energyRange,
            "valenceRange": valenceRange,
            "tempoRange": tempoRange
        ]
        return config
    }
}

