import SwiftUI

struct MainView: View {
    @State private var spotifyService = SpotifyService.shared
    @State private var playlistManager = PlaylistManager()
    @State private var heartRateModel = HeartRateModel()
    @State private var configService = ConfigService.shared
    @State private var selectedTab = 0
    @State private var isLoading = false
    @State private var statusMessage = "Ready"

    var body: some View {
        ZStack {
            // Dark background
            Color(red: 0.02, green: 0.04, blue: 0.05)
                .ignoresSafeArea()

            VStack(spacing: 0) {
                // Header
                PulseHeaderView()

                // Tab Navigation
                HStack(spacing: 0) {
                    TabButton(title: "Discover", isSelected: selectedTab == 0) {
                        selectedTab = 0
                    }
                    TabButton(title: "Playlists", isSelected: selectedTab == 1) {
                        selectedTab = 1
                    }
                    TabButton(title: "Settings", isSelected: selectedTab == 2) {
                        selectedTab = 2
                    }
                }
                .background(Color(red: 0.05, green: 0.08, blue: 0.12))

                // Content
                TabView(selection: $selectedTab) {
                    DiscoverView(playlistManager: playlistManager, heartRateModel: heartRateModel, statusMessage: $statusMessage, isLoading: $isLoading)
                        .tag(0)

                    PlaylistsView(playlistManager: playlistManager)
                        .tag(1)

                    SettingsView(configService: configService, heartRateModel: heartRateModel)
                        .tag(2)
                }
                .tabViewStyle(.page(indexDisplayMode: .never))

                // Status Bar
                PulseStatusBar(status: statusMessage, isLoading: isLoading)
            }
        }
    }
}

struct TabButton: View {
    let title: String
    let isSelected: Bool
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            VStack(spacing: 4) {
                Text(title)
                    .font(.system(size: 12, weight: .semibold, design: .monospaced))
                    .foregroundColor(isSelected ? Color(red: 0.0, green: 1.0, blue: 0.8) : Color(red: 0.42, green: 0.6, blue: 0.6))

                if isSelected {
                    Capsule()
                        .fill(Color(red: 0.0, green: 1.0, blue: 0.8))
                        .frame(height: 2)
                }
            }
            .frame(maxWidth: .infinity)
            .padding(.vertical, 12)
        }
        .buttonStyle(.plain)
    }
}

