import SwiftUI

struct DiscoverView: View {
    @State var playlistManager: PlaylistManager
    @State var heartRateModel: HeartRateModel
    @Binding var statusMessage: String
    @Binding var isLoading: Bool

    @State private var playlistName = "My PULSE Playlist"
    @State private var showAlert = false
    @State private var alertMessage = ""

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                // Playlist Name Input
                VStack(alignment: .leading, spacing: 8) {
                    Label {
                        Text("Playlist Name")
                            .font(.system(size: 11, weight: .semibold, design: .monospaced))
                            .foregroundColor(Color(red: 0.0, green: 0.94, blue: 1.0))
                    } icon: {
                        Image(systemName: "music.note")
                            .foregroundColor(Color(red: 0.0, green: 1.0, blue: 0.8))
                    }

                    TextField("Playlist name...", text: $playlistName)
                        .textFieldStyle(.roundedBorder)
                        .font(.system(size: 11, design: .monospaced))
                }
                .padding()
                .background(Color(red: 0.05, green: 0.08, blue: 0.12))
                .cornerRadius(6)

                // Create Playlist Button
                Button(action: createPlaylist) {
                    HStack(spacing: 8) {
                        Image(systemName: "sparkles")
                        Text("SUMMON PLAYLIST")
                            .font(.system(size: 11, weight: .bold, design: .monospaced))
                            .letterSpacing(1.2)
                    }
                    .frame(maxWidth: .infinity)
                    .padding(.vertical, 12)
                    .background(Color(red: 0.0, green: 0.83, blue: 0.67))
                    .foregroundColor(Color(red: 0.02, green: 0.04, blue: 0.05))
                    .cornerRadius(6)
                    .font(.system(size: 11, weight: .bold))
                }
                .disabled(isLoading)

                // Stats
                HStack(spacing: 12) {
                    StatCard(icon: "♥", label: "Playlists", value: "\(playlistManager.playlists.count)")
                    StatCard(icon: "♡", label: "Tracks", value: "\(playlistManager.playlists.flatMap { $0.tracks }.count)")
                    StatCard(icon: "💙", label: "Heart Rate", value: "\(heartRateModel.currentHeartRate)")
                }

                Spacer()
            }
            .padding()
        }
        .alert("Playlist Created", isPresented: $showAlert) {
            Button("OK") { }
        } message: {
            Text(alertMessage)
        }
    }

    private func createPlaylist() {
        isLoading = true
        statusMessage = "Creating playlist..."

        DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
            let newPlaylist = PulsePlaylist(
